#!/usr/bin/env node
/**
 * build-core-bundle.mjs
 *
 * 從 monorepo @choulegal/core-inheritance 編出單一 ESM bundle 給民眾版民法計算機用。
 * 取代原本散在 js/core/*.js 的本地副本，讓計算邏輯有 single source of truth。
 *
 * 用法：node scripts/build-core-bundle.mjs
 * 輸出：js/_generated/core-inheritance.bundle.js（ESM、含 sourcemap）
 *
 * Monorepo 路徑透過環境變數 CHOULEGAL_MONOREPO 覆寫，預設 ~/Desktop/choulegal
 */
import { build } from 'esbuild';
import { join, dirname, relative } from 'node:path';
import { mkdir, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { homedir } from 'node:os';

const __dirname = dirname(fileURLToPath(import.meta.url));
const CONSUMER_REPO = join(__dirname, '..');
const MONOREPO = process.env.CHOULEGAL_MONOREPO || join(homedir(), 'Desktop', 'choulegal');
const ENTRY = join(MONOREPO, 'packages', 'core-inheritance', 'src', 'index.js');
const OUT_DIR = join(CONSUMER_REPO, 'js', '_generated');
const OUT_FILE = join(OUT_DIR, 'core-inheritance.bundle.js');

await mkdir(OUT_DIR, { recursive: true });

const result = await build({
  entryPoints: [ENTRY],
  bundle: true,
  format: 'esm',
  outfile: OUT_FILE,
  sourcemap: true,
  target: ['es2020'],
  banner: {
    js: `// AUTO-GENERATED by scripts/build-core-bundle.mjs from ${relative(CONSUMER_REPO, ENTRY)}\n// DO NOT EDIT MANUALLY. Run \`npm run build:core\` to regenerate.\n// Source of truth: ${MONOREPO}/packages/core-inheritance/`,
  },
  metafile: true,
  logLevel: 'info',
});

const stats = Object.entries(result.metafile.outputs)[0][1];
console.log(`\n✓ Bundle: ${relative(CONSUMER_REPO, OUT_FILE)}`);
console.log(`  ${stats.bytes.toLocaleString()} bytes (${(stats.bytes / 1024).toFixed(1)} KB)`);
console.log(`  ${Object.keys(result.metafile.inputs).length} source files bundled`);
